import type { TableMeta } from '../src/types.js';

// Bens e serviços com alíquota de IBS e CBS reduzida a zero (100%) ou em 60%: LC 214/2025, Anexos I a XV (Anexo XIV, de medicamentos,
// revogado pela LC 227/2026). Um item por linha do anexo, com os códigos de NCM e de NBS citados na linha (só dígitos; "0306" é a
// posição, "03061" a subposição, "03061100" o código). A parte entre `<generated>` e `</generated>` é gerada do texto oficial
// (`npm run gen:reducoes`) e conferida por `npm run verify:sources`. Não editar à mão.
//
// Isto NÃO decide a alíquota: o código casar com o anexo é condição necessária, não suficiente. A maioria dos itens exige
// "conformidade com os requisitos da legislação específica", tem ressalvas ("exceto...") ou depende de destinação; quem classifica o
// produto confirma. A função de consulta devolve CANDIDATOS.

export interface ReductionItem {
  annex: string;
  /** Redução das alíquotas de IBS e CBS, em %: "100" (zero) ou "60". */
  reductionPct: string;
  item: string;
  /** Linha de grupo do anexo (p.ex. "ACESSÓRIOS E ADAPTAÇÕES ESPECIAIS..."), quando o item é filho. */
  group: string | null;
  description: string;
  /** Prefixos de NCM (dígitos): capítulo (2), posição (4), subposição (5 a 6), código (7 a 8). */
  ncm: string[];
  /** Prefixos de NBS (dígitos). */
  nbs: string[];
}

